import React from 'react';

function JobStats({ jobs }) {
  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-6">
      <div className="bg-white rounded-lg shadow p-6 flex flex-col items-start">
        <div className="text-sm text-gray-500 mb-1">Total Jobs</div>
        <div className="text-3xl font-bold text-gray-900">{jobs.length}</div>
      </div>
      <div className="bg-white rounded-lg shadow p-6 flex flex-col items-start">
        <div className="text-sm text-gray-500 mb-1">Full-time Positions</div>
        <div className="text-3xl font-bold text-gray-900">
          {jobs.filter(j => j.jobType === 'Full-time').length}
        </div>
      </div>
      <div className="bg-white rounded-lg shadow p-6 flex flex-col items-start">
        <div className="text-sm text-gray-500 mb-1">Part-time Positions</div>
        <div className="text-3xl font-bold text-gray-900">
          {jobs.filter(j => j.jobType === 'Part-time').length}
        </div>
      </div>
    </div>
  );
}

export default JobStats;
